insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1236, 'Tree Distances', 'A tree has n nodes and n − 1 roads with lengths. Answer q questions: what is the distance between nodes u and v, that is, the total length of the roads on the path between them?', 'The first line contains n and q (1 ≤ n, q ≤ 2·10^4). Each of the next n − 1 lines contains u, v and w: a road of length w (1 ≤ w ≤ 10^6) between u and v. Each of the next q lines contains a question u v (1 ≤ u, v ≤ n).', 'For each question print the distance on its own line.', '', '[{"input":"5 3\n1 2 3\n1 3 4\n3 4 2\n3 5 6\n2 4\n4 5\n1 1\n","output":"9\n8\n0"}]'::jsonb, array['trees','graphs','binary lifting']::text[], 2100, 2000, 'public') on conflict (id) do nothing;
