insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1238, 'Weak Bridges', 'A road network has n towns and m two-way roads. A road is critical if, after closing it, some two towns that could reach each other before can no longer reach each other. How many critical roads are there? There may be several roads between the same two towns, but no road connects a town to itself.', 'The first line contains n and m (1 ≤ n ≤ 2·10^4, 0 ≤ m ≤ 2·10^4). Each of the next m lines contains u and v (1 ≤ u, v ≤ n, u ≠ v).', 'Print the number of critical roads.', '', '[{"input":"5 5\n1 2\n2 3\n3 1\n3 4\n4 5\n","output":"2"},{"input":"2 2\n1 2\n2 1\n","output":"0"}]'::jsonb, array['graphs','dfs and similar']::text[], 2300, 2000, 'public') on conflict (id) do nothing;
